function domOf(rn) {
  if (rn <= 85)  return 'PB1'
  if (rn <= 220) return 'linker'
  if (rn <= 260) return 'ZZ'
  if (rn <= 480) return 'linker'
  if (rn <= 620) return 'CC'
  if (rn <= 740) return 'LIR'
  if (rn <= 870) return 'linker'
  return 'UBA'
}

